responseSchemaJson:
{
  "type": "object",
  "description": "状态处理系统基于<History>创建/更新角色的最新状态。所有输出内容必须为简体中文(zh-CN)。",
  "properties": {
    "data": {
      "type": "object",
      "description": "[数据模块] 包含结构化角色状态信息。",
      "properties": {
        "createdCharacterInfo": {
          "type": "object",
          "description": "创建`{{源角色名称}}`的当前状态。所有描述字段必须为中文数组。若无内容，请使用`['无']`。",
          "properties": {
            "characterName": {
              "type": "string",
              "description": "正在生成状态的角色名称：`{{源角色名称}}`。"
            },
            "hairstyle": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "角色当前的发型。"
            },
            "demeanor": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "角色当前可观察到的神态/表情/姿态。"
            },
            "clothing": {
              "type": "object",
              "description": "角色当前可观察到的着装状态。将所有衣物归类为外层或内层。",
              "properties": {
                "outerwear": {
                  "type": "array",
                  "items": {
                    "type": "string"
                  },
                  "description": "所有可见的外层衣物列表（包括外套、上装、下装、鞋袜、外穿配饰等）。"
                },
                "underwear": {
                  "type": "array",
                  "items": {
                    "type": "string"
                  },
                  "description": "所有内层衣物列表（包括内衣裤、贴身衣物等）。"
                }
              },
              "required": [
                "outerwear",
                "underwear"
              ],
              "propertyOrdering": [
                "outerwear",
                "underwear"
              ]
            },
            "accessories": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "可观察到的佩戴饰品及其状态（不含衣物附件）。"
            },
            "shortTermStatus": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "可直接观察到的具体短期生理状态。"
            },
            "actionPose": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "概括角色当前可观察到的身体姿势/主要动作的关键词。"
            },
            "currentPosition": {
              "type": "array",
              "items": {
                "type": "string"
              },
              "description": "描述角色具有战术或互动意义的最新相对位置/状态。"
            }
          },
          "required": [
            "characterName",
            "hairstyle",
            "demeanor",
            "clothing",
            "accessories",
            "shortTermStatus",
            "actionPose",
            "currentPosition"
          ],
          "propertyOrdering": [
            "characterName",
            "hairstyle",
            "demeanor",
            "clothing",
            "accessories",
            "shortTermStatus",
            "actionPose",
            "currentPosition"
          ]
        }
      },
      "required": [
        "createdCharacterInfo"
      ],
      "propertyOrdering": [
        "createdCharacterInfo"
      ]
    },
    "test": {
      "type": "object",
      "description": "[模块二：测试] 包含用于评估模型特定能力的附加任务。",
      "properties": {
        "problemsAndSolutions": {
          "type": "array",
          "description": "包含3对高等数学问题及其解法的列表。",
          "items": {
            "type": "object",
            "properties": {
              "problem": {
                "type": "string",
                "description": "高等数学问题。"
              },
              "solution": {
                "type": "string",
                "description": "对应问题的解法。"
              }
            },
            "required": [
              "problem",
              "solution"
            ],
            "propertyOrdering": [
              "problem",
              "solution"
            ]
          },
          "minItems": 3,
          "maxItems": 3
        }
      },
      "required": [
        "problemsAndSolutions"
      ],
      "propertyOrdering": [
        "problemsAndSolutions"
      ]
    }
  },
  "required": [
    "data",
    "test"
  ],
  "propertyOrdering": [
    "data",
    "test"
  ]
}

responseSchemaParserJs:
const rawText = responseJson.candidates[0].content.parts[0].text;
const jsonString = rawText.substring(rawText.indexOf('{'), rawText.lastIndexOf('}') + 1);
const charInfo = JSON.parse(jsonString).data.createdCharacterInfo;
charInfo.hairstyle = charInfo.hairstyle.map(str => {
    const idx = str.lastIndexOf('色');
    return idx !== -1 ? str.substring(idx + 1) : str;
});
charInfo.shortTermStatus = charInfo.shortTermStatus.filter(i => !i.includes('发'));
return {
    processedCharacterInfo: {
        characterName: charInfo.characterName,
        demeanorItems: charInfo.demeanor,
        outerwearItems: charInfo.clothing.outerwear,
        underwearItems: charInfo.clothing.underwear,
        accessories: charInfo.accessories,
        shortTermStatusItems: [...charInfo.hairstyle, ...charInfo.shortTermStatus],
        actionPoseItems: charInfo.actionPose,
        currentPositionItems: charInfo.currentPosition
    }
};

